files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  min-width: 500px;
  min-height: 100vh;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
}

.swiper {
  width: 100%;
  height: 100vh;
  margin: 0;
}

.swiper-slide {
  display: flex;
  justify-content: center;
  align-items: center;
  color: #000;
  font-weight: bold;
  font-size: 100px;
  text-align: center;
  text-transform: uppercase;
}

.swiper-slide:nth-child(even) {
  background-color: #feafe8;
}

.swiper-slide:nth-child(odd) {
  background-color: #80d994;
}


.swiper-button {
  border: none;
  background-color: transparent;
}

.swiper-button::after {
  color: black;
}

.swiper-pagination-bullet {
  background-color: #000;
}
/* Перекрываем более специфичные правила внешней библиотеки Swiper. */
.swiper-pagination-bullet {
  margin: 0 20px !important;
}

.swiper-pagination {
  bottom: 40px !important;
}
